// Lazy-loaded generated files for agent sessions and resource chats.
//
// Agent sessions produce file attachments during runs. Resource chats have
// agent-authored messages with attachments. This module fetches those on demand
// when expanded in the sidebar, deduplicates by key, and returns a flat list.
//
// For agent sessions: turns carry both human INPUT attachments (in prompt) and
// agent OUTPUT attachments (in response). We filter to outputs only by checking
// which attachments are referenced in the response, not the prompt.
//
// For resource chats: we filter to messages where authorKind === "agent".

import {
  listAgentTurns,
  type NeevAgentTurn,
} from "./neev-agent-sessions-client"
import { listNativeMessages } from "./neev-content-client"

/** A file generated by the agent, with context for ordering. */
export interface SessionFile {
  /** The attachment key, used for downloads and as the dedupe key. */
  key: string
  fileName: string
  contentType: string
  byteLength: number
  /** The sequence (turn or message) that produced this file, for ordering. */
  sequence: string
}

/**
 * All supported attachment types are displayable.
 *
 * HTML is supported as text/plain by the server. The browser may block certain
 * downloads due to org policy, but we still list the file - the policy blocks
 * bypassing, not hiding. Users need to see what files exist.
 */
const SUPPORTED_TYPES = [
  "image/png",
  "image/jpeg",
  "image/webp",
  "application/pdf",
  "text/plain",
]

/** Whether an attachment type is one the server supports. */
export function isSupportedType(contentType: string): boolean {
  return SUPPORTED_TYPES.includes(contentType)
}

/** Format bytes in human-readable form (B, KB, MB). */
export function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

/** Match the generated-output links persisted by the server, as in the chat view. */
function getResponseAttachmentKeys(turn: NeevAgentTurn): Set<string> {
  return new Set(
    turn.attachments
      .filter(
        (file) =>
          turn.response.includes(`/api/neev/attachments/${file.key}`) &&
          !turn.prompt.includes(file.key)
      )
      .map((file) => file.key)
  )
}

/**
 * Fetch generated files for an agent session, walking pagination and deduping.
 *
 * Only attachments that appear in the turn's RESPONSE (not prompt) are included.
 * These are the agent outputs. Human inputs are in the prompt.
 */
export async function listAgentSessionFiles(
  sessionId: string,
  signal?: AbortSignal
): Promise<SessionFile[]> {
  const seen = new Set<string>()
  const files: SessionFile[] = []

  let cursor: string | null = null
  const cursors = new Set<string>()

  for (;;) {
    if (signal?.aborted) break

    const result = await listAgentTurns(sessionId, cursor, signal)

    for (const turn of result.items) {
      // Get only the attachments referenced in the response (agent outputs).
      const outputKeys = getResponseAttachmentKeys(turn)

      for (const attachment of turn.attachments) {
        // Skip if not an output (it's a human input from the prompt).
        if (!outputKeys.has(attachment.key)) continue
        // Skip duplicates.
        if (seen.has(attachment.key)) continue
        // Skip unsupported types (shouldn't happen but defensive).
        if (!isSupportedType(attachment.contentType)) continue

        seen.add(attachment.key)
        files.push({
          key: attachment.key,
          fileName: attachment.fileName,
          contentType: attachment.contentType,
          byteLength: attachment.byteLength,
          sequence: turn.sequence,
        })
      }
    }

    cursor = result.nextAfter
    if (cursor === null) break
    if (cursors.has(cursor)) throw new Error("Repeated file-list cursor")
    cursors.add(cursor)
  }

  // Sort by sequence ascending (files appear in creation order).
  files.sort((a, b) => {
    const seqA = BigInt(a.sequence)
    const seqB = BigInt(b.sequence)
    if (seqA < seqB) return -1
    if (seqA > seqB) return 1
    return 0
  })

  return files
}

/**
 * Fetch generated files for a resource chat (team chat).
 *
 * Only attachments from messages where authorKind === "agent" are included.
 * Human uploads are on messages where authorKind === "human".
 */
export async function listResourceChatFiles(
  chatId: string,
  signal?: AbortSignal
): Promise<SessionFile[]> {
  const seen = new Set<string>()
  const files: SessionFile[] = []

  let cursor: string | null = null
  const cursors = new Set<string>()

  for (;;) {
    if (signal?.aborted) break

    const result = await listNativeMessages(chatId, cursor, signal)

    for (const message of result.items) {
      // Only include attachments from agent-authored messages.
      if (message.authorKind !== "agent") continue

      for (const attachment of message.attachments) {
        if (seen.has(attachment.key)) continue
        if (!isSupportedType(attachment.contentType)) continue

        seen.add(attachment.key)
        files.push({
          key: attachment.key,
          fileName: attachment.fileName,
          contentType: attachment.contentType,
          byteLength: attachment.byteLength,
          sequence: message.sequence,
        })
      }
    }

    cursor = result.nextAfter
    if (cursor === null) break
    if (cursors.has(cursor)) throw new Error("Repeated file-list cursor")
    cursors.add(cursor)
  }

  // Sort by sequence ascending.
  files.sort((a, b) => {
    const seqA = BigInt(a.sequence)
    const seqB = BigInt(b.sequence)
    if (seqA < seqB) return -1
    if (seqA > seqB) return 1
    return 0
  })

  return files
}
